public void addCommandResponse(TFMCommandResponse _commandResponse)
{
    if (!commandResponses)
    {
        commandResponses = new List(Types::Class);
    }
    commandResponses.addEnd(_commandResponse);
}

public static TFMCommandResponses Construct()
{
    return new TFMCommandResponses();
}

public void appendToXML(XmlElement _element)
{
    if (commandResponses)
    {
        XmlElement commandResponsesElement = _element.ownerDocument().createElement('commands');
        ListEnumerator enum = commandResponses.getEnumerator();
        while (enum.moveNext())
        {
            TFMCommandResponse commandResponse = enum.current() as TFMCommandResponse;
            if (commandResponse)
            {

                commandResponse.appendToXML(commandResponsesElement);

            }
        }
        _element.appendChild(commandResponsesElement);
    }
}
